insert into public.waiver_versions (version, texts) values
  (1, '{"en":["I train at my own risk and will use the equipment safely.","I have no medical condition that stops me exercising, or my doctor says it''s OK.","I''ll follow the gym rules and the staff''s directions."],"th":["ฉันออกกำลังกายโดยยอมรับความเสี่ยงเอง และจะใช้อุปกรณ์อย่างปลอดภัย","ฉันไม่มีโรคประจำตัวที่ห้ามออกกำลังกาย หรือแพทย์อนุญาตแล้ว","ฉันจะปฏิบัติตามกฎของยิมและคำแนะนำของพนักงาน"],"ru":["Я тренируюсь на свой риск и безопасно пользуюсь оборудованием.","У меня нет противопоказаний к нагрузкам, или врач разрешил тренировки.","Я соблюдаю правила зала и указания персонала."]}'::jsonb)
